  use Veltrion\Services\Commercial\Licensing\Contracts\MachineIdentityProviderInterface; class MachineIdentity implements MachineIdentityProviderInterface { public function getMachineFingerprint(): array { $os = PHP_OS_FAMILY; $hostname = gethostname() ?: 'unknown'; $cpuInfo = ''; $diskInfo = ''; if ($os === 'Windows') { $cpuInfo = shell_exec('wmic cpu get ProcessorId 2>NUL') ?: ''; $diskInfo = shell_exec('wmic diskdrive get SerialNumber 2>NUL') ?: ''; } else if ($os === 'Linux') { if (file_exists('/etc/machine-id')) { $cpuInfo = trim(file_get_contents('/etc/machine-id')); } else if (file_exists('/var/lib/dbus/machine-id')) { $cpuInfo = trim(file_get_contents('/var/lib/dbus/machine-id')); } $diskInfo = shell_exec('uname -m -r 2>/dev/null') ?: ''; } else { $cpuInfo = php_uname(); } $rawFingerprint = [ 'os' => $os, 'hostname' => $hostname, 'arch' => PHP_INT_SIZE * 8 . '-bit', 'cpu' => trim(preg_replace('/\s+/', ' ', $cpuInfo)), 'disk' => trim(preg_replace('/\s+/', ' ', $diskInfo)) ]; return $rawFingerprint; } public function getMachineId(): string { $fp = $this->getMachineFingerprint(); $str = implode('|', [$fp['os'], $fp['hostname'], $fp['cpu'], $fp['disk']]); $hash = strtoupper(hash('sha256', $str)); return sprintf( '%s-%s-%s-%s', substr($hash, 0, 4), substr($hash, 4, 4), substr($hash, 8, 4), substr($hash, 12, 4) ); } } 